-- Importance: 100. Pair access, versions, retry receipts, and list invariants protect shared data.
begin;
\ir fixtures/setup.sql
select plan(67);
select has_table('public','task_lists');
select has_table('public','tasks');
-- Importance: 95. Remove the obsolete unversioned RPC.
select has_function('public','rename_list',array['uuid','text','integer','uuid'],'Versioned list rename RPC exists');
select hasnt_function('public','rename_list',array['uuid','text','uuid'],'Unversioned list rename RPC is absent');
select is((select count(*)::integer from public.task_lists where is_general),2,'General exists for active fixture pairs');
select ok(not has_table_privilege('authenticated','public.tasks','INSERT'),'No direct task inserts');
select ok(not has_table_privilege('authenticated','public.tasks','UPDATE'),'No direct task updates');
select ok(not has_table_privilege('authenticated','public.tasks','DELETE'),'No direct task deletes');
select ok(not has_table_privilege('authenticated','public.task_lists','INSERT'),'No direct list inserts');
select ok(not has_table_privilege('authenticated','public.task_lists','UPDATE'),'No direct list updates');
select ok(not has_table_privilege('authenticated','public.task_lists','DELETE'),'No direct list deletes');
select ok(not has_function_privilege('anon','public.create_task(jsonb,uuid)','EXECUTE'),'Anon cannot call task create');
select ok(not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename in('tasks','task_lists')),'No content DELETE streams');
select ok(exists(select 1 from pg_policies where schemaname='realtime' and policyname='task_signals_read' and cmd='SELECT'),'Private broadcast has read policy');
select pg_temp.as_user(1);
set local role authenticated;
create temporary table general as select id from public.task_lists where is_general and pair_id='30000000-0000-4000-8000-000000000001';
create temporary table list_saved as select public.create_list('30000000-0000-4000-8000-000000000001','Groceries','60000000-0000-4000-8000-000000000001') result;
select ok((select (result->>'ok')::boolean from list_saved),'Create list');
select is(public.create_list('30000000-0000-4000-8000-000000000001','Groceries','60000000-0000-4000-8000-000000000001'),(select result from list_saved),'List retry');
select is(public.create_list('30000000-0000-4000-8000-000000000001','gROCERIES','60000000-0000-4000-8000-000000000002')->'error'->>'code','CONFLICT','Case-insensitive names');
select is(public.rename_list((select id from general),'Daily',1,'50000000-0000-4000-8000-000000000001')->'error'->>'code','FORBIDDEN','General cannot be renamed');
select is(public.delete_empty_list((select id from general),'50000000-0000-4000-8000-000000000002')->'error'->>'code','FORBIDDEN','General cannot be deleted');
-- Importance: 98. Stale names must conflict, and retries must preserve their original version.
create temporary table rename_fixture as select public.create_list('30000000-0000-4000-8000-000000000001','Rename fixture','60000000-0000-4000-8000-000000000003') result;
create temporary table rename_saved as select public.rename_list('60000000-0000-4000-8000-000000000003','First name',1,'50000000-0000-4000-8000-000000000040') result;
select is((select result->'data'->>'version' from rename_saved),'2','Rename advances the saved version once');
select pg_temp.as_user(2);
select is(public.rename_list('60000000-0000-4000-8000-000000000003','Second name',1,'50000000-0000-4000-8000-000000000041')->'error'->>'code','CONFLICT','Partner stale name conflicts');
select is((select name from public.task_lists where id='60000000-0000-4000-8000-000000000003'),'First name','Stale rename preserves the winner name');
select is((select version from public.task_lists where id='60000000-0000-4000-8000-000000000003'),2,'Stale rename preserves the winner version');
select pg_temp.as_user(1);
select is(public.rename_list('60000000-0000-4000-8000-000000000003','First name',1,'50000000-0000-4000-8000-000000000040'),(select result from rename_saved),'Rename retry replays the original receipt');
select is(public.rename_list('60000000-0000-4000-8000-000000000003','First name',2,'50000000-0000-4000-8000-000000000040')->'error'->>'code','CONFLICT','Rename receipt binds the expected version');
select is(public.rename_list('60000000-0000-4000-8000-000000000003','No version',null,'50000000-0000-4000-8000-000000000042')->'error'->>'code','CONFLICT','Rename requires an expected version');
select is(public.rename_list('60000000-0000-4000-8000-000000000003','Invalid version',0,'50000000-0000-4000-8000-000000000043')->'error'->>'code','CONFLICT','Rename rejects invalid versions');
select is(public.rename_list('60000000-0000-4000-8000-000000000003','Groceries',2,'50000000-0000-4000-8000-000000000044')->'error'->>'field','name','Name collision identifies the name field');
select is(public.rename_list('60000000-0000-4000-8000-000000000003','Reviewed name',2,'50000000-0000-4000-8000-000000000045')->'data'->>'version','3','Reviewed version permits a new rename command');
select is(public.rename_list('60000000-0000-4000-8000-000000000003','First name',1,'50000000-0000-4000-8000-000000000040'),(select result from rename_saved),'Late retry returns its original receipt without overwriting');
create temporary table input as select '{"id":"40000000-0000-4000-8000-000000000001","pair_id":"30000000-0000-4000-8000-000000000001","list_id":"60000000-0000-4000-8000-000000000001","title":"Buy bread","assignee_id":null,"due_date":"2026-10-04"}'::jsonb value;
create temporary table task_saved as select public.create_task((select value from input),'50000000-0000-4000-8000-000000000010') result;
select ok((select (result->>'ok')::boolean from task_saved),'Create task');
select is(public.create_task((select value from input),'50000000-0000-4000-8000-000000000010'),(select result from task_saved),'Task retry');
select is(public.create_task((select value||'{"title":"Changed request"}' from input),'50000000-0000-4000-8000-000000000010')->'error'->>'code','CONFLICT','Receipt binds request');
select is(public.create_task((select value||'{"id":"40000000-0000-4000-8000-000000000002","assignee_id":"10000000-0000-4000-8000-000000000003"}' from input),'50000000-0000-4000-8000-000000000011')->'error'->>'code','VALIDATION','Other pair assignee rejected');
select is(public.create_task((select value||'{"id":"40000000-0000-4000-8000-000000000002","due_date":"2026-02-30"}' from input),'50000000-0000-4000-8000-000000000012')->'error'->>'code','VALIDATION','Invalid due date rejected');
select is(public.delete_empty_list('60000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000013')->'error'->>'field','listNotEmpty','Nonempty list deletion denied');
create temporary table completed as select public.set_task_completed('40000000-0000-4000-8000-000000000001',true,1,'50000000-0000-4000-8000-000000000014') result;
select is((select result->'data'->>'version' from completed),'2','Completion advances version');
select is(public.set_task_completed('40000000-0000-4000-8000-000000000001',true,1,'50000000-0000-4000-8000-000000000014'),(select result from completed),'Duplicate completion command replays');
select is(public.set_task_completed('40000000-0000-4000-8000-000000000001',true,2,'50000000-0000-4000-8000-000000000015')->'data'->>'version','2','Desired completed state does not toggle');
select pg_temp.as_user(2);
select is((select count(*)::integer from public.tasks),1,'Partner reads shared task');
select is(public.set_task_completed('40000000-0000-4000-8000-000000000001',false,2,'50000000-0000-4000-8000-000000000016')->'data'->>'version','3','Partner reopens task');
select ok((select completed_at is null and completed_by is null from public.tasks where id='40000000-0000-4000-8000-000000000001'),'Reopen clears completion identity');
select ok((public.update_task('40000000-0000-4000-8000-000000000001',(select value||'{"title":"Partner edit"}' from input),3,'50000000-0000-4000-8000-000000000017')->>'ok')::boolean,'Partner edits title');
select pg_temp.as_user(1);
select is(public.update_task('40000000-0000-4000-8000-000000000001',(select value from input),3,'50000000-0000-4000-8000-000000000018')->'error'->>'code','CONFLICT','Stale title edit denied');
select is(public.move_list_tasks_to_general('60000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000019')->'data'->>'moved','1','Explicit move to General');
select is((select version from public.tasks where id='40000000-0000-4000-8000-000000000001'),5,'Move advances task version');
select ok((public.delete_empty_list('60000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000020')->>'ok')::boolean,'Delete empty list');
select ok((public.delete_empty_list('60000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000020')->>'ok')::boolean,'Replay list delete receipt');
select pg_temp.as_user(3);
select is((select count(*)::integer from public.tasks),0,'Third account cannot read other pair tasks');
select is(public.set_task_completed('40000000-0000-4000-8000-000000000001',true,5,'50000000-0000-4000-8000-000000000021')->'error'->>'code','FORBIDDEN','Cross-pair command rejected');
select pg_temp.as_user(1);
reset role;
select throws_ok($$update public.tasks set created_by='10000000-0000-4000-8000-000000000002' where id='40000000-0000-4000-8000-000000000001'$$,'P0001','FORBIDDEN','Immutable author');
select throws_ok($$update public.tasks set pair_id='30000000-0000-4000-8000-000000000002' where id='40000000-0000-4000-8000-000000000001'$$,'P0001','FORBIDDEN','Immutable pair');
select throws_ok($$update public.tasks set list_id=(select id from public.task_lists where pair_id='30000000-0000-4000-8000-000000000002' and is_general) where id='40000000-0000-4000-8000-000000000001'$$,'23503',null,'Composite list foreign key rejects cross-pair reference');
update public.profiles set account_status='disabled' where user_id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.update_task('40000000-0000-4000-8000-000000000001',
  (select value||jsonb_build_object('list_id',(select id from general),'assignee_id','10000000-0000-4000-8000-000000000002') from input),5,
  '50000000-0000-4000-8000-000000000030')->'error'->>'code','VALIDATION','Disabled assignee rejected');
reset role;
update public.profiles set account_status='active' where user_id='10000000-0000-4000-8000-000000000002';
update public.pair_members set left_at=now() where user_id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.update_task('40000000-0000-4000-8000-000000000001',
  (select value||jsonb_build_object('list_id',(select id from general),'assignee_id','10000000-0000-4000-8000-000000000002') from input),5,
  '50000000-0000-4000-8000-000000000031')->'error'->>'code','VALIDATION','Former assignee rejected');
reset role;
update public.pair_members set left_at=null where user_id='10000000-0000-4000-8000-000000000002';
update public.profiles set account_status='disabled' where user_id='10000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::integer from public.tasks),0,'Disabled account cannot read tasks');
select is(public.create_task((select value from input),'50000000-0000-4000-8000-000000000010')->'error'->>'code','FORBIDDEN','Disabled account cannot replay receipt');
-- Importance: 100. Rename receipts must recheck current access.
select is(public.rename_list('60000000-0000-4000-8000-000000000003','First name',1,'50000000-0000-4000-8000-000000000040')->'error'->>'code','FORBIDDEN','Disabled account cannot replay rename');
reset role;
update public.profiles set account_status='active' where user_id='10000000-0000-4000-8000-000000000001';
delete from auth.sessions where id='20000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::integer from public.tasks),0,'Revoked session cannot read tasks');
select is(public.create_task((select value from input),'50000000-0000-4000-8000-000000000010')->'error'->>'code','UNAUTHENTICATED','Revoked session cannot replay receipt');
select is(public.rename_list('60000000-0000-4000-8000-000000000003','First name',1,'50000000-0000-4000-8000-000000000040')->'error'->>'code','UNAUTHENTICATED','Revoked session cannot replay rename');
reset role;
insert into auth.sessions(id,user_id,created_at,updated_at) values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',now(),now());
insert into public.pairs(id,state,timezone) values('30000000-0000-4000-8000-000000000003','pending','Europe/Warsaw');
select is((select count(*)::integer from public.task_lists where pair_id='30000000-0000-4000-8000-000000000003'),0,'Pending pair has no General');
update public.pairs set state='active' where id='30000000-0000-4000-8000-000000000003';
select is((select count(*)::integer from public.task_lists where pair_id='30000000-0000-4000-8000-000000000003' and is_general),1,'Activation creates General');
update public.pairs set state='active' where id='30000000-0000-4000-8000-000000000003';
select is((select count(*)::integer from public.task_lists where pair_id='30000000-0000-4000-8000-000000000003' and is_general),1,'Repeated activation keeps one General');
update public.pairs set state='ended',ended_at=now() where id='30000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::integer from public.tasks),0,'Ended pair cannot read tasks');
select is(public.create_task((select value from input),'50000000-0000-4000-8000-000000000010')->'error'->>'code','FORBIDDEN','Current membership required before receipt replay');
select is(public.rename_list('60000000-0000-4000-8000-000000000003','First name',1,'50000000-0000-4000-8000-000000000040')->'error'->>'code','FORBIDDEN','Ended pair cannot replay rename');
select * from finish();
rollback;
